exports.push([module.i, "@charset \"UTF-8\";\r\n/**\r\n * 这里是uni-app内置的常用样式变量\r\n *\r\n * uni-app 官方扩展插件及插件市场（https://ext.dcloud.net.cn）上很多三方插件均使用了这些样式变量\r\n * 如果你是插件开发者，建议你使用scss预处理，并在插件代码中直接使用这些变量（无需 import 这个文件），方便用户通过搭积木的方式开发整体风格一致的App\r\n *\r\n */\r\n/**\r\n * 如果你是App开发者（插件使用者），你可以通过修改这些变量来定制自己的插件主题，实现自定义主题功能\r\n *\r\n * 如果你的项目同样使用了scss预处理，你也可以直接在你的 scss 代码中使用如下变量，同时无需 import 这个文件\r\n */\r\n/* 颜色变量 */\r\n/* 行为相关颜色 */\r\n/* 文字基本颜色 */\r\n/* 背景颜色 */\r\n/* 边框颜色 */\r\n/* 尺寸变量 */\r\n/* 文字尺寸 */\r\n/* 图片尺寸 */\r\n/* Border Radius */\r\n/* 水平间距 */\r\n/* 垂直间距 */\r\n/* 透明度 */\r\n/* 文章场景相关 */\n.match-list[data-v-45ee15ba] {\r\n  background-color: #f5f5f5;\r\n  box-sizing: border-box;\r\n  padding-bottom: 140rpx;\n}\n.drawer-wrapper[data-v-45ee15ba] {\r\n  width: 100%;\r\n  margin-bottom: 8rpx;\r\n  background: #f5f5f5;\n}\n.sticky-header[data-v-45ee15ba] {\r\n  position: -webkit-sticky;\r\n  position: sticky;\r\n  z-index: 999;\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  box-sizing: border-box;\r\n  padding: 8rpx 20rpx 12rpx 20rpx;\r\n  background-color: #f5f5f5;\r\n  border-bottom: 1rpx solid #eee;\r\n  font-size: 26rpx;\r\n  color: #333;\n}\n.sticky-header .drawer-title-text[data-v-45ee15ba] {\r\n  font-size: 24rpx;\r\n  color: #333;\n}\n.sticky-header .arrow-icon[data-v-45ee15ba] {\r\n  transition: -webkit-transform 0.2s ease;\r\n  transition: transform 0.2s ease;\r\n  transition: transform 0.2s ease, -webkit-transform 0.2s ease;\r\n  font-size: 24rpx;\r\n  color: #666;\n}\n.sticky-header .rotated[data-v-45ee15ba] {\r\n  -webkit-transform: rotate(180deg);\r\n          transform: rotate(180deg);\n}\n.drawer-content[data-v-45ee15ba] {\r\n  width: 100%;\r\n  transition: all 0.2s ease;\n}\n.match-row[data-v-45ee15ba] {\r\n  background-color: #fff;\r\n  border-bottom: 1rpx solid #DEDEDE;\r\n  box-sizing: border-box;\r\n  padding: 0rpx 20rpx;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 0;\r\n  margin-bottom: 4rpx;\r\n  border-radius: 8rpx;\r\n  box-shadow: 0 2rpx 5rpx rgba(0, 0, 0, 0.05);\r\n  width: 100%;\r\n  overflow: hidden;\n}\n.main-content-row[data-v-45ee15ba] {\r\n  box-sizing: border-box;\r\n  display: flex;\r\n  width: 100%;\r\n  gap: 16rpx;\r\n  padding: 8rpx 0;\r\n  overflow: hidden;\n}\r\n/* 左侧场次号 */\n.main-left[data-v-45ee15ba] {\r\n  width: 160rpx;\r\n  display: flex;\r\n  flex: none;\r\n  align-items: center;\r\n  justify-content: center;\n}\n.match-num-wrapper[data-v-45ee15ba] {\r\n  width: 100%;\r\n  height: 100%;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\n}\n.match-num[data-v-45ee15ba] {\r\n  font-size: 28rpx;\r\n  color: #333;\r\n  font-weight: 500;\n}\r\n/* 右侧内容 */\n.main-right[data-v-45ee15ba] {\r\n  flex: 1;\r\n  width: calc(100% - 176rpx);\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 8rpx;\r\n  background: #fff;\r\n  box-sizing: border-box;\r\n  overflow: hidden;\n}\n.top-right[data-v-45ee15ba] {\r\n  flex: 1;\r\n  text-align: center;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 6rpx;\r\n  width: 100%;\r\n  box-sizing: border-box;\r\n  overflow: hidden;\n}\r\n/* 队名行：绝对对称布局，为对齐锁死尺寸 */\n.team-vs[data-v-45ee15ba] {\r\n  font-size: 24rpx;\r\n  color: #333;\r\n  display: flex;\r\n  align-items: center;\r\n  width: 100%;\r\n  cursor: pointer;\r\n  transition: all 0.2s ease;\r\n  /* 主队名容器：固定占比，右对齐 */\r\n  /* VS容器：固定80rpx，居中（和你截图一致） */\r\n  /* 客队名容器：固定占比，左对齐 */\n}\n.team-vs[data-v-45ee15ba]:active {\r\n  color: #d92929;\r\n  opacity: 0.8;\n}\n.team-vs .team-name.home[data-v-45ee15ba] {\r\n  width: calc((100% - 80rpx) / 2.1);\r\n  text-align: right;\r\n  padding-right: 10rpx;\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\n}\n.team-vs .vs-text[data-v-45ee15ba] {\r\n  width: 100rpx;\r\n  text-align: center;\r\n  flex-shrink: 0;\r\n  font-weight: 500;\n}\n.team-vs .team-name.away[data-v-45ee15ba] {\r\n  width: calc((100% - 80rpx) / 2.1);\r\n  text-align: left;\r\n  padding-left: 10rpx;\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\n}\r\n/* 胜行：和队名行1:1复刻尺寸，绝对对齐 */\n.rate-row[data-v-45ee15ba] {\r\n  width: 100%;\r\n  display: flex;\r\n  align-items: center;\r\n  font-size: 22rpx;\r\n  color: #999;\r\n  /* 主队胜容器：和主队名尺寸/对齐完全一致 */\r\n  /* 平容器：和VS尺寸/对齐完全一致 */\r\n  /* 客队胜容器：和客队名尺寸/对齐完全一致 */\r\n  /* 分析按钮：不影响对齐，单独靠外 */\n}\n.rate-row .rate-text.home[data-v-45ee15ba] {\r\n  width: calc((100% - 80rpx) / 2.1);\r\n  text-align: right;\r\n  padding-right: 10rpx;\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\n}\n.rate-row .vs-text[data-v-45ee15ba] {\r\n  width: 80rpx;\r\n  text-align: center;\r\n  flex-shrink: 0;\r\n  color: #999;\r\n  font-size: 20rpx;\n}\n.rate-row .rate-text.away[data-v-45ee15ba] {\r\n  text-align: left;\r\n  padding-left: 20rpx;\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\n}\n.rate-row .ai-analysis-btn[data-v-45ee15ba] {\r\n  font-size: 22rpx;\r\n  color: #06f;\r\n  cursor: pointer;\r\n  transition: opacity 0.2s;\r\n  flex-shrink: 0;\r\n  margin-left: 12rpx;\n}\n.rate-row .ai-analysis-btn[data-v-45ee15ba]:active {\r\n  opacity: 0.8;\n}\r\n/* 比分矩阵样式 */\n.bottom-right[data-v-45ee15ba] {\r\n  width: 100%;\r\n  box-sizing: border-box;\r\n  overflow: hidden;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  border: 1rpx solid #f1f1f1;\n}\n.score-matrix[data-v-45ee15ba] {\r\n  width: 100%;\r\n  border-collapse: collapse;\r\n  background-color: #fff;\n}\n.matrix-row[data-v-45ee15ba] {\r\n  display: flex;\r\n  width: 100%;\r\n  border-bottom: 1rpx solid #ddd;\n}\n.matrix-row[data-v-45ee15ba]:last-child {\r\n  border-bottom: none;\n}\n.matrix-label[data-v-45ee15ba] {\r\n  width: 80rpx;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  background-color: #f5f5f5;\r\n  border-right: 1rpx solid #ddd;\r\n  font-size: 26rpx;\r\n  color: #333;\n}\n.matrix-cell[data-v-45ee15ba] {\r\n  flex: 1;\r\n  height: 60rpx;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-size: 26rpx;\r\n  color: #333;\r\n  border-right: 1rpx solid #ddd;\r\n  transition: all 0.2s ease;\n}\n.matrix-cell[data-v-45ee15ba]:last-child {\r\n  border-right: none;\n}\n.matrix-cell.selected[data-v-45ee15ba] {\r\n  background-color: #d92929;\r\n  color: #fff;\n}\n.matrix-cell[data-v-45ee15ba]:active {\r\n  background-color: #f0f0f0;\n}\n.matrix-cell.selected[data-v-45ee15ba]:active {\r\n  background-color: #c62828;\n}\r\n/* 兼容优化 */\n[data-v-45ee15ba]::-webkit-scrollbar {\r\n  display: none;\n}\n.score-popup[data-v-45ee15ba] {\r\n  padding-bottom: calc(20rpx + constant(safe-area-inset-bottom));\r\n  padding-bottom: calc(20rpx + env(safe-area-inset-bottom));\n}\nuni-button[data-v-45ee15ba]::after {\r\n  border: none;\n}\r\n", ""]);
